#include <stdio.h>

int main(void) {
    long long n;
    int m;

    if (scanf("%lld", &n) != 1) return 0;
    scanf("%d", &m);

    int t[5000];
    for (int i = 0; i < m; i++) {
        scanf("%d", &t[i]);
        n -= n / t[i];
    }

    long long limit = n < 10000 ? n : 10000;

    for (long long rank = 1; rank <= limit; rank++) {
        long long subject = rank;
        for (int i = m - 1; i >= 0; i--) {
            subject += (subject - 1) / (t[i] - 1);
        }
        printf("%lld\n", subject);
    }

    return 0;
}
